const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Jakarta Bay area
  const jakartaBay = ee.Geometry.Polygon([
    [[106.7, -6.0], [106.95, -6.0], [106.95, -6.2], [106.7, -6.2], [106.7, -6.0]]
  ]);

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Calculate MNDWI (Modified Normalized Difference Water Index)
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Baseline period (2015-2016, before major construction)
  const baseline = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(jakartaBay)
    .filterDate('2015-01-01', '2016-12-31')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(addMNDWI);

  const baselineSize = baseline.size().getInfo();
  console.log(`Baseline images (2015-2016): ${baselineSize}`);

  if (baselineSize === 0) {
    console.log('No baseline data available');
    console.log('<answer>C1</answer>');
    return;
  }

  // 2021 period (target year)
  const target2021 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(jakartaBay)
    .filterDate('2021-01-01', '2021-12-31')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .map(addMNDWI);

  const target2021Size = target2021.size().getInfo();
  console.log(`2021 images: ${target2021Size}`);

  if (target2021Size === 0) {
    console.log('No 2021 data available');
    console.log('<answer>C1</answer>');
    return;
  }

  // Create median composites
  const baselineMedian = baseline.median();
  const target2021Median = target2021.median();

  // Classify water (MNDWI > 0 indicates water)
  const baselineWater = baselineMedian.select('MNDWI').gt(0);
  const target2021Water = target2021Median.select('MNDWI').gt(0);

  // New artificial land: water in baseline, land in 2021
  const newLand = baselineWater.and(target2021Water.not());

  // Calculate pixel count of new land
  const pixelCount = newLand.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: jakartaBay,
    scale: 1000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`New land pixels (1000m scale): ${pixelCount}`);

  if (pixelCount === null || pixelCount === undefined) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  if (pixelCount === 0) {
    console.log('No valid pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate area in hectares (1000m scale = 1,000,000 m² per pixel = 100 hectares per pixel)
  const areaHectares = pixelCount * 100;
  console.log(`Estimated new artificial land area: ${areaHectares.toFixed(0)} hectares`);

  // Check if area > 800 hectares
  if (areaHectares > 800) {
    console.log('Area exceeds 800 hectares threshold');
    console.log('<answer>A</answer>');
  } else {
    console.log('Area below 800 hectares threshold');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
